def _bridge_spans(axle_count: int) -> list[tuple[int, int]]:
    """Every group of two or more consecutive axles, front to back.

    The formula applies to each group, not just the outer bridge. Sliding the
    tandems forward can overload an interior group while the outer span, the
    single limits and the tandem limits all pass.
    """
    return [
        (first, last)
        for first in range(axle_count - 1)
        for last in range(first + 1, axle_count)
    ]

